package dev.saffron;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;
import static org.springframework.http.HttpStatus.*;
@Service class ChannelOperations {
 private final JdbcTemplate db;private final ChannelGateway gateway;
 ChannelOperations(JdbcTemplate db,ChannelGateway gateway){this.db=db;this.gateway=gateway;}
 record Setting(long version,boolean enabled,String destination,String p256dh,String auth){}
 static String mask(String destination){if(destination==null||destination.isEmpty())return "";if(destination.startsWith("local://")||destination.startsWith("https://"))return "Registered browser";int at=destination.indexOf('@');if(at>0)return destination.charAt(0)+"***"+destination.substring(at);return "***"+destination.substring(Math.max(0,destination.length()-4));}
 private void ensure(String subject){for(String c:List.of("EMAIL","SMS","PUSH"))db.update("insert into notification_channel_settings(subject,channel,mode) values(?,?,?) on conflict do nothing",subject,c,gateway.mode(c));}
 public Object settings(String subject){ensure(subject);var rows=db.queryForList("select channel,enabled,version,destination from notification_channel_settings where subject=? order by channel",subject);for(var r:rows){r.put("mode",gateway.mode(r.get("channel").toString()));if(!r.get("channel").equals("PUSH"))r.put("contact",r.get("destination"));r.put("destination",mask(r.get("destination").toString()));}return Map.of("channels",rows,"vapidPublicKey",gateway.vapidPublic());}
 @Transactional public Object save(String subject,String channel,Setting input,String verifiedEmail,String verifiedPhone){String mode=gateway.mode(channel);ensure(subject);var current=db.queryForMap("select * from notification_channel_settings where subject=? and channel=? for update",subject,channel);if(((Number)current.get("version")).longValue()!=input.version)throw new ResponseStatusException(CONFLICT,"Channel preferences changed; refresh");String destination="",subscription="{}";
 if(input.enabled){if(mode.equals("disabled"))throw new ResponseStatusException(SERVICE_UNAVAILABLE,"Channel is not configured");destination=input.destination==null?"":input.destination;
 if(channel.equals("EMAIL")){ChannelGateway.email(destination);if(mode.equals("local")){if(!destination.endsWith(".test")&&!destination.endsWith(".invalid"))throw new IllegalArgumentException("Local email must end in .test or .invalid");}else if(verifiedEmail==null||!destination.equals(verifiedEmail))throw new ResponseStatusException(FORBIDDEN,"Identity-provider verified email required");}
 if(channel.equals("SMS")){ChannelGateway.phone(destination);if(mode.equals("local")){if(!destination.matches("\\+1555[0-9]{7}"))throw new IllegalArgumentException("Local SMS uses +1555 fixture numbers only");}else if(verifiedPhone==null||!destination.equals(verifiedPhone))throw new ResponseStatusException(FORBIDDEN,"Identity-provider verified phone required");}
 if(channel.equals("PUSH")){if(mode.equals("local")){if(!destination.matches("local://[a-f0-9-]{36}"))throw new IllegalArgumentException("Local browser registration required");}else{try{ChannelGateway.pushEndpoint(destination);ChannelGateway.pushKeys(input.p256dh,input.auth);}catch(Exception e){throw new IllegalArgumentException("Invalid push subscription");}subscription=JsonMapper.builder().build().writeValueAsString(Map.of("p256dh",input.p256dh,"auth",input.auth));}}
 }
 if(current.get("enabled").equals(input.enabled)&&current.get("mode").equals(mode)&&current.get("destination").equals(destination)&&JsonMapper.builder().build().readTree(current.get("subscription").toString()).equals(JsonMapper.builder().build().readTree(subscription)))return Map.of("version",input.version);
 db.update("update notification_channel_settings set enabled=?,mode=?,destination=?,subscription=?::jsonb,version=version+1,updated_at=now() where subject=? and channel=?",input.enabled,mode,destination,subscription,subject,channel);
 db.update("update notification_deliveries set state='CANCELLED',last_error='Preference changed before dispatch',updated_at=now() where subject=? and channel=? and state in ('QUEUED','RETRY') and provider_id is null",subject,channel);
 db.update("insert into audit(actor,action,resource) values(?,?,?)",subject,input.enabled?"NOTIFICATION_CHANNEL_ENABLED":"NOTIFICATION_CHANNEL_DISABLED",channel);return Map.of("version",input.version+1);
 }
 void enqueue(UUID notification,String subject){db.update("insert into notification_deliveries(id,notification_id,subject,channel,mode,destination,subscription,setting_version) select gen_random_uuid(),?,subject,channel,mode,destination,subscription,version from notification_channel_settings where subject=? and enabled on conflict(notification_id,channel) do nothing",notification,subject);}
 @Transactional public List<Map<String,Object>> claim(){
 db.update("update notification_deliveries set state=case when mode='local' and attempts<5 then 'RETRY' else 'UNKNOWN' end,last_error='Worker lease expired; outcome unresolved',lease_until='-infinity',lease_token=null where state='SENDING' and lease_until<now()");
 db.update("update notification_deliveries set state='UNKNOWN',last_error='Delivery outcome did not converge within three days' where (state='RETRY' or (state='ACCEPTED' and mode in ('local','twilio'))) and created_at<now()-interval '3 days'");
 var rows=db.queryForList("select d.*,n.title,n.href from notification_deliveries d join notifications n on n.id=d.notification_id where d.lease_until<now() and d.next_attempt<=now() and (d.state in ('QUEUED','RETRY') or (d.state='ACCEPTED' and d.mode in ('local','twilio'))) order by d.next_attempt,d.created_at limit 5 for update of d skip locked");
 for(var d:rows){UUID token=UUID.randomUUID();d.put("lease_token",token);db.update("update notification_deliveries set lease_token=?,lease_until=now()+interval '5 minutes',state=case when provider_id is null then 'SENDING' else state end,attempts=attempts+case when provider_id is null then 1 else 0 end where id=?",token,d.get("id"));}return rows;
 }
 @Transactional public boolean permitted(Map<String,Object> job){var refs=db.queryForList("select enabled,version,mode from notification_channel_settings where subject=? and channel=?",job.get("subject"),job.get("channel"));boolean valid=!refs.isEmpty()&&Boolean.TRUE.equals(refs.getFirst().get("enabled"))&&refs.getFirst().get("version").equals(job.get("setting_version"))&&refs.getFirst().get("mode").equals(gateway.mode(job.get("channel").toString()))&&job.get("mode").equals(gateway.mode(job.get("channel").toString()));if(!valid&&job.get("provider_id")==null){db.update("update notification_deliveries set state='CANCELLED',last_error='Consent or provider configuration changed',lease_until='-infinity',lease_token=null where id=? and lease_token=?",job.get("id"),job.get("lease_token"));return false;}if(!job.get("mode").equals(gateway.mode(job.get("channel").toString()))){db.update("update notification_deliveries set state='UNKNOWN',last_error='Restore original provider configuration to reconcile',lease_until='-infinity',lease_token=null where id=? and lease_token=?",job.get("id"),job.get("lease_token"));return false;}return true;}
 @Transactional public void result(Map<String,Object> job,ChannelGateway.Result result){var rows=db.queryForList("select * from notification_deliveries where id=? for update",job.get("id"));var row=rows.getFirst();if(!Objects.equals(row.get("lease_token"),job.get("lease_token")))return;String state=result.state();if(state.equals("RETRY")&&((Number)row.get("attempts")).intValue()>=5)state="UNKNOWN";db.update("update notification_deliveries set state=?,provider_id=coalesce(?,provider_id),last_error=?,next_attempt=now()+make_interval(secs=>least(30,power(2,least(attempts,4))::int)),lease_until='-infinity',lease_token=null,updated_at=now() where id=?",state,result.reference(),result.error(),job.get("id"));if(result.expired()&&job.get("channel").equals("PUSH"))db.update("update notification_channel_settings set enabled=false,version=version+1,updated_at=now() where subject=? and channel='PUSH' and version=?",job.get("subject"),job.get("setting_version"));}
 public Object history(String subject){var rows=db.queryForList("select d.id,d.notification_id,d.channel,d.mode,d.destination,d.state,d.attempts,d.provider_id,d.last_error,d.created_at,d.displayed_at,n.title from notification_deliveries d join notifications n on n.id=d.notification_id where d.subject=? order by d.created_at desc limit 100",subject);for(var row:rows)row.put("destination",mask(row.get("destination").toString()));return rows;}
 public Object localMessage(String subject,UUID id)throws Exception{var rows=db.queryForList("select mode,provider_id from notification_deliveries where id=? and subject=?",id,subject);if(rows.isEmpty())throw new ResponseStatusException(NOT_FOUND);var row=rows.getFirst();if(!row.get("mode").equals("local")||row.get("provider_id")==null)throw new ResponseStatusException(CONFLICT,"No local mailbox receipt yet");var data=gateway.localMessage(row.get("provider_id").toString());return Map.of("title",data.path("title").asString(),"body",data.path("body").asString(),"href",data.path("href").asString());}
 public Object localPush(String subject,String device){return db.queryForList("select d.id,n.title,n.href from notification_deliveries d join notifications n on n.id=d.notification_id join notification_channel_settings s on s.subject=d.subject and s.channel='PUSH' where d.subject=? and d.channel='PUSH' and d.mode='local' and d.destination=? and d.state='DELIVERED' and d.displayed_at is null and s.enabled and s.version=d.setting_version order by d.created_at limit 20",subject,device);}
 @Transactional public void displayed(String subject,UUID id){if(db.update("update notification_deliveries set displayed_at=coalesce(displayed_at,now()),state='DELIVERED' where id=? and subject=? and channel='PUSH' and state in ('ACCEPTED','DELIVERED')",id,subject)==0)throw new ResponseStatusException(NOT_FOUND);}
}
